// Fast local lookup set for instant word validation
const WORD_SETS: Record<number, Set<string>> = {};
for (const [len, words] of Object.entries(WORD_LISTS)) {
  WORD_SETS[Number(len)] = new Set(words.map(w => w.toUpperCase()));
}

// Client-side cache for dynamically validated dictionary words
const validatedCache = new Set<string>();

/**
 * Synchronous validation against local curated word sets and session cache.
 */
export function isValidWord(word: string, length: number): boolean {
  if (!word) return false;
  const clean = word.trim().toUpperCase();
  if (clean.length !== length) return false;

  return Boolean(WORD_SETS[length]?.has(clean) || validatedCache.has(clean));
}

/**
 * Comprehensive asynchronous validation:
 * 1. Checks local curated set & session cache first (0ms instant response)
 * 2. If not found locally, validates against the complete 280,000+ English dictionary
 *    (supporting all verbs, tenses, adjectives, adverbs, plurals, and inflections)
 * 3. Automatically caches confirmed valid words in memory
 */
export async function isValidWordAsync(word: string, length: number): Promise<boolean> {
  if (!word) return false;
  const clean = word.trim().toUpperCase();
  if (clean.length !== length) return false;

  // 1. Instant local check
  if (isValidWord(clean, length)) {
    return true;
  }

  // 2. Query complete dictionary endpoint
  try {
    const res = await fetch(`/api/words/validate?word=${encodeURIComponent(clean)}&length=${length}`);
    if (res.ok) {
      const data = await res.json();
      if (data && data.valid) {
        validatedCache.add(clean);
        return true;
      }
    }
  } catch (err) {
    console.warn('Dictionary validation fetch warning:', err);
  }

  return false;
}

export function getRandomWord(length: number): string {
  const list = WORD_LISTS[length] || WORD_LISTS[5];
  const idx = Math.floor(Math.random() * list.length);
  return list[idx].toUpperCase();
}
